import json
import collections

# Retrieve parameters directly from the globally injected 'input_data' dictionary
map_id = input_data['map_id']
start_x = int(input_data['start_x'])
start_y = int(input_data['start_y'])
target_x = int(input_data['target_x'])
target_y = int(input_data['target_y'])

def find_path():
    max_x = 40
    max_y = 36

    plateau_tiles = set()
    impassable_ground = set()

    if map_id == "0_220": # Center
        for x in range(8, 22):
            for y in range(8, 14):
                impassable_ground.add((x, y))
        for x in range(0, 18):
            impassable_ground.add((x, 15))
            impassable_ground.add((x, 16))
        for x in range(22, 28):
            impassable_ground.add((x, 9))
        for x in range(28, 30):
            impassable_ground.add((x, 9))
        impassable_ground.add((15, 24))

    elif map_id == "0_217": # East
        for x in range(11, 24):
            for y in range(12, 22):
                plateau_tiles.add((x, y))
        for x in range(11, 24):
            for y in range(2, 8):
                plateau_tiles.add((x, y))

        for x in range(13, 20):
            for y in range(10, 12):
                impassable_ground.add((x, y))
        for y in range(4, 8):
            impassable_ground.add((19, y))
        for x in range(0, 11):
            impassable_ground.add((x, 6))
        impassable_ground.add((0, 2))

        for x in range(11, 24):
            impassable_ground.add((x, 12))
            impassable_ground.add((x, 21))
            impassable_ground.add((x, 2))
            impassable_ground.add((x, 7))

    elif map_id == "0_218": # North
        for x in range(33, 39):
            for y in range(12, 15):
                plateau_tiles.add((x, y))
        for x in range(37, 39):
            for y in range(15, 26):
                plateau_tiles.add((x, y))
        for x in range(28, 39):
            plateau_tiles.add((x, 26))

        for x in range(14, 25):
            for y in range(20, 23):
                plateau_tiles.add((x, y))
        for x in range(14, 19):
            plateau_tiles.add((x, 23))

        for y in range(11, 20):
            impassable_ground.add((16, y))
        for y in range(24, 29):
            impassable_ground.add((26, y))
        for x in range(30, 40):
            impassable_ground.add((x, 27))
        for x in range(10, 20):
            impassable_ground.add((x, 34))
        for x in range(38, 40):
            for y in range(28, 30):
                impassable_ground.add((x, y))
            for y in range(32, 34):
                impassable_ground.add((x, y))
        for x in range(0, 40):
            impassable_ground.add((x, 11))
        for y in range(20, 23):
            impassable_ground.add((25, y))
        for x in range(19, 22):
            impassable_ground.add((x, 23))
        impassable_ground.add((25, 23))
        for y in range(20, 24):
            impassable_ground.add((14, y))

    elif map_id == "0_219": # West
        # Main central plateau
        for x in range(11, 17):
            for y in range(6, 25):
                plateau_tiles.add((x, y))
        # Eastern plateau extension
        for x in range(17, 22):
            for y in range(14, 18):
                plateau_tiles.add((x, y))
        # Western plateau extension (Fully corrected to include Columns 5-11 on Rows 16 and 17)
        for x in range(5, 12):
            for y in range(16, 19):
                plateau_tiles.add((x, y))
        for x in range(6, 11):
            for y in range(19, 20):
                plateau_tiles.add((x, y))

        for x in range(1, 3):
            impassable_ground.add((x, 14))
            impassable_ground.add((x, 15))
        for x in range(2, 9):
            impassable_ground.add((x, 13))
        for y in range(1, 13):
            impassable_ground.add((24, y))
        for x in range(24, 26):
            for y in range(0, 3):
                impassable_ground.add((x, y))
        for x in range(11, 16):
            impassable_ground.add((x, 25))
        for x in range(18, 30):
            impassable_ground.add((x, 25))

    def check_stairs(cx, cy, nx, ny, move, on_plat):
        next_plat = on_plat
        if map_id == "0_217":
            if (cx, cy) == (20, 22) and (nx, ny) == (20, 21) and move == "Up":
                next_plat = True
            elif (cx, cy) == (20, 20) and (nx, ny) == (20, 21) and move == "Down":
                next_plat = False
            elif (cx, cy) == (10, 20) and (nx, ny) == (11, 20) and move == "Right":
                next_plat = True
            elif (cx, cy) == (12, 20) and (nx, ny) == (11, 20) and move == "Left":
                next_plat = False
            elif (cx, cy) == (12, 8) and (nx, ny) == (12, 7) and move == "Up":
                next_plat = True
            elif (cx, cy) == (12, 6) and (nx, ny) == (12, 7) and move == "Down":
                next_plat = False
            elif (cx, cy) == (17, 8) and (nx, ny) == (17, 7) and move == "Up":
                next_plat = True
            elif (cx, cy) == (17, 6) and (nx, ny) == (17, 7) and move == "Down":
                next_plat = False
        elif map_id == "0_218":
            if (cx, cy) == (34, 16) and (nx, ny) == (34, 15) and move == "Up":
                next_plat = True
            elif (cx, cy) == (34, 14) and (nx, ny) == (34, 15) and move == "Down":
                next_plat = False
            elif (cx, cy) == (28, 28) and (nx, ny) == (28, 27) and move == "Up":
                next_plat = True
            elif (cx, cy) == (28, 26) and (nx, ny) == (28, 27) and move == "Down":
                next_plat = False
            elif (cx, cy) == (22, 24) and (nx, ny) == (22, 23) and move == "Up":
                next_plat = True
            elif (cx, cy) == (22, 22) and (nx, ny) == (22, 23) and move == "Down":
                next_plat = False
            elif (cx, cy) == (16, 28) and (nx, ny) == (16, 27) and move == "Up":
                next_plat = True
            elif (cx, cy) == (16, 26) and (nx, ny) == (16, 27) and move == "Down":
                next_plat = False
        elif map_id == "0_219":
            if (cx, cy) == (21, 18) and (nx, ny) == (21, 17) and move == "Up":
                next_plat = True
            elif (cx, cy) == (21, 16) and (nx, ny) == (21, 17) and move == "Down":
                next_plat = False
            elif (cx, cy) == (21, 17) and (nx, ny) == (21, 18) and move == "Down":
                next_plat = False
            elif (cx, cy) == (6, 20) and (nx, ny) == (6, 19) and move == "Up":
                next_plat = True
            elif (cx, cy) == (6, 18) and (nx, ny) == (6, 19) and move == "Down":
                next_plat = False
            elif (cx, cy) == (6, 19) and (nx, ny) == (6, 20) and move == "Down":
                next_plat = False
        return next_plat

    start_on_plat = (start_x, start_y) in plateau_tiles
    queue = collections.deque([(start_x, start_y, start_on_plat, [])])
    visited = {(start_x, start_y, start_on_plat)}

    while queue:
        cx, cy, on_plat, path = queue.popleft()
        if (cx, cy) == (target_x, target_y):
            return path

        for dx, dy, move in [(0, -1, "Up"), (0, 1, "Down"), (-1, 0, "Left"), (1, 0, "Right")]:
            nx, ny = cx + dx, cy + dy
            if not (0 <= nx < max_x and 0 <= ny < max_y):
                continue

            next_plat = check_stairs(cx, cy, nx, ny, move, on_plat)

            if next_plat:
                is_stair = False
                if map_id == "0_217":
                    is_stair = (nx, ny) in [(20, 21), (11, 20), (12, 7), (17, 7)]
                elif map_id == "0_218":
                    is_stair = (nx, ny) in [(34, 15), (28, 27), (22, 23), (16, 27)]
                elif map_id == "0_219":
                    is_stair = (nx, ny) in [(21, 17), (6, 19)]

                if (nx, ny) not in plateau_tiles and not is_stair:
                    continue
            else:
                if (nx, ny) in impassable_ground:
                    continue
                if (nx, ny) in plateau_tiles:
                    continue
                if map_id == "0_218" and ny < 11 and (nx, ny) != (34, 16):
                    continue

            state = (nx, ny, next_plat)
            if state not in visited:
                visited.add(state)
                queue.append((nx, ny, next_plat, path + [move]))

    return []

path = find_path()
print(json.dumps(path))
